window.kbPageData["views/entry/k-036485e66ac9034c"] = {"key":"entry/k-036485e66ac9034c","state":{"route":"entry/k-036485e66ac9034c"},"node":{"id":"k-036485e66ac9034c","mode":"k","title":"退化耕地分区治理","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["南方粮食主产区治理耕地酸化，盐碱集中地区示范耕作压盐"],"qs":["国考 2023 地市级 行测#6"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"《“十四五”全国农业绿色发展规划》提出，在长江中下游、西南和华南等南方粮食主产区推进酸化耕地降酸改良，在西北灌溉区、滨海灌溉区和松嫩平原西部等盐碱集中地区示范耕作压盐等技术，推进盐碱耕地改良。","review":{"definition":"《“十四五”全国农业绿色发展规划》提出，在长江中下游、西南和华南等南方粮食主产区推进酸化耕地降酸改良，在西北灌溉区、滨海灌溉区和松嫩平原西部等盐碱集中地区示范耕作压盐等技术，推进盐碱耕地改良。","explanation":"规划按耕地退化类型和地区配置治理措施。D项把适用于盐碱集中地区的耕作压盐示范放到了长江中下游、西南等南方粮食主产区，错配了地区与技术，因此是本题应选的错误项。","references":[],"evidence":"在长江中下游、西南地区等南方粮食主产区集中示范耕作压盐技术模式","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#6":{"paper":"国考 2023 地市级 行测","n":6,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",2],"asrc":["f3ab652d8e31c5bbdabc.pdf",2],"card":"62e6c598bc157bb0c0fe57d0","links":[{"id":"k-036485e66ac9034c","role":"直接考查","why":"识别治理措施的适用地区，需要区分酸化耕地降酸与盐碱耕地压盐。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-036485e66ac9034c":[["国考 2023 地市级 行测#6"]]}};
